import Vue from 'vue'
import Vuex from 'vuex'
import { posts } from './posts.js'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    posts
  },
  getters: {
    getPostById(state) {
      return state.posts.find(post => post.id === state.posts.find(post => {}))
    }
  },
  mutations: {
  },
  actions: {
  },
  modules: {
  }
})
